/**
 * Turns a title into a slug for a URL or a file name: `slugify('Hello,  World!')` is `'hello-world'`.
 * Accents are stripped; a title with nothing left gives `''`.
 * @param {string} title
 * @returns {string}
 */
export function slugify(title) {
  return title
    .normalize('NFD')
    .replace(/\p{M}/gu, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { slugify } from '../src/slugify.js';

test('slugify lowercases', () => {
  assert.equal(slugify('Kiln'), 'kiln');
});

test('spaces and runs of punctuation become one dash', () => {
  assert.equal(slugify('Hello,  World!'), 'hello-world');
});

test('leading and trailing dashes are trimmed', () => {
  assert.equal(slugify('--Hi--'), 'hi');
});

test('accents are stripped', () => {
  assert.equal(slugify('Café au lait'), 'cafe-au-lait');
});

test('a title with nothing left gives an empty string', () => {
  assert.equal(slugify('!!!'), '');
});

