// Prints the slug of its arguments: `node src/cli.js Hello, World!` prints `hello-world`.
import { slugify } from './slugify.js';

const title = process.argv.slice(2).join(' ');
if (!title) {
  console.error('Usage: node src/cli.js <title>');
  process.exit(1);
}
console.log(slugify(title));

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const cli = fileURLToPath(new URL('../src/cli.js', import.meta.url));
const run = (...args) => spawnSync(process.execPath, [cli, ...args], { encoding: 'utf8' });

test('the CLI prints the slug of its arguments', () => {
  const { status, stdout } = run('Hello,', 'World!');
  assert.equal(status, 0);
  assert.equal(stdout, 'hello-world\n');
});

test('the CLI with no title prints its usage and exits with 1', () => {
  const { status, stderr } = run();
  assert.equal(status, 1);
  assert.match(stderr, /Usage/);
});
